function drawMahoukarpBlueWhale(ctx, cx, cy, breath, angle, scale, time) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  // Squash & Stretch 5% volume conservation
  const sy = 1.0 + 0.05 * Math.sin(angle);
  const sx = 1.0 / Math.sqrt(sy);
  const by = Math.sin(angle) * 3.5;

  const tailLag = Math.sin(angle - 0.75);
  const finLag  = Math.sin(angle - 0.40);

  // Tail Fluke
  ctx.save();
  ctx.translate(46 * sx, by - 2 * sy + tailLag * 6.0);
  const tailGrad = ctx.createLinearGradient(0, -15, 15, 15);
  tailGrad.addColorStop(0, '#BFA6EC');
  tailGrad.addColorStop(1, '#9C9DE8');
  ctx.fillStyle = tailGrad;
  ctx.beginPath();
  ctx.ellipse(8, -8, 11, 7, -0.2, 0, Math.PI * 2);
  ctx.ellipse(8, 8, 11, 7, 0.2, 0, Math.PI * 2);
  ctx.fill();
  // Notch cut
  ctx.fillStyle = '#060B18'; // Dark bg cut
  ctx.beginPath();
  ctx.moveTo(11, 0);
  ctx.lineTo(20, -6);
  ctx.lineTo(20, 6);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  // Whale Body Gradient
  const bodyGrad = ctx.createLinearGradient(-48 * sx, by - 26 * sy, 48 * sx, by + 26 * sy);
  bodyGrad.addColorStop(0, '#A6D2F7');
  bodyGrad.addColorStop(0.4, '#C5A3E0');
  bodyGrad.addColorStop(1, '#8E89D6');

  ctx.fillStyle = bodyGrad;
  ctx.beginPath();
  ctx.ellipse(-2 * sx, by, 48 * sx, 25 * sy, 0, 0, Math.PI * 2);
  ctx.fill();

  // Underbelly Creamy White
  ctx.fillStyle = '#F3F8FE';
  ctx.beginPath();
  ctx.ellipse(-10 * sx, by + 10 * sy, 36 * sx, 15 * sy, 0.05, 0, Math.PI);
  ctx.fill();

  // Throat Pleat Grooves
  ctx.strokeStyle = '#D2E4F9';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.ellipse(-10 * sx, by + 10 * sy, 32 * sx, 10 * sy, 0.05, 0.1, Math.PI - 0.1);
  ctx.stroke();
  ctx.beginPath();
  ctx.ellipse(-12 * sx, by + 13 * sy, 27 * sx, 7 * sy, 0.05, 0.15, Math.PI - 0.15);
  ctx.stroke();

  // Pectoral Fin
  ctx.save();
  ctx.translate(-12 * sx, by + 12 * sy + finLag * 3.0);
  ctx.fillStyle = '#9C9DE8';
  ctx.beginPath();
  ctx.ellipse(0, 0, 11 * sx, 5 * sy, 0.3, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  // Star Blossom Flowers on Dorsal Back
  function drawFlower(fx, fy, colPetal, colCenter) {
    ctx.fillStyle = colPetal;
    for (let r = 0; r < 4; r++) {
      const ang = (r * Math.PI) / 2;
      ctx.beginPath();
      ctx.arc(fx + Math.cos(ang) * 2.6, fy + Math.sin(ang) * 2.6, 2.2, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.fillStyle = colCenter;
    ctx.beginPath();
    ctx.arc(fx, fy, 2.0, 0, Math.PI * 2);
    ctx.fill();
  }
  drawFlower(8 * sx, by - 14 * sy, '#FFB8D6', '#FFFFFF');
  drawFlower(24 * sx, by - 9 * sy, '#FFD2E5', '#FFFFFF');
  drawFlower(18 * sx, by - 3 * sy, '#FFFFFF', '#FFAEC9');

  // Cheek Glow & Blush
  ctx.fillStyle = 'rgba(255, 255, 255, 0.6)';
  ctx.beginPath();
  ctx.arc(-22 * sx, by + 4 * sy, 7.5, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#FFAEC9';
  ctx.beginPath();
  ctx.ellipse(-22 * sx, by + 4 * sy, 5.5, 4.0, 0, 0, Math.PI * 2);
  ctx.fill();

  // Crystal Eye with 3 Catchlights
  const eyeX = -32 * sx, eyeY = by + 2 * sy;
  const blink = (time % 4000 < 140);
  if (blink) {
    ctx.strokeStyle = '#0B1220';
    ctx.lineWidth = 2.0;
    ctx.beginPath();
    ctx.arc(eyeX, eyeY + 2, 4, Math.PI * 1.1, Math.PI * 1.9);
    ctx.stroke();
  } else {
    ctx.fillStyle = '#0B1220';
    ctx.beginPath();
    ctx.arc(eyeX, eyeY, 4.2, 0, Math.PI * 2);
    ctx.fill();
    // Catchlight 1: Main top-left
    ctx.fillStyle = '#FFFFFF';
    ctx.beginPath();
    ctx.arc(eyeX - 1.2, eyeY - 1.8, 1.8, 0, Math.PI * 2);
    ctx.fill();
    // Catchlight 2: Secondary bounce bottom-right
    ctx.beginPath();
    ctx.arc(eyeX + 1.6, eyeY + 1.2, 1.0, 0, Math.PI * 2);
    ctx.fill();
    // Catchlight 3: Micro twinkle
    ctx.fillStyle = '#D8E2FD';
    ctx.beginPath();
    ctx.arc(eyeX + 1.8, eyeY - 1.0, 0.6, 0, Math.PI * 2);
    ctx.fill();
  }

  // Cute mouth smile
  ctx.strokeStyle = '#706DB3';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.arc(-38 * sx, by + 6 * sy, 3, 0.1, Math.PI * 0.8);
  ctx.stroke();

  // Spout bubbles
  const spoutLag = Math.sin(angle - 0.90);
  ctx.fillStyle = '#A6D2F7';
  ctx.beginPath();
  ctx.arc(-18 * sx, by - 28 * sy + spoutLag * 2, 2.5, 0, Math.PI * 2);
  ctx.arc(-14 * sx, by - 33 * sy + spoutLag * 2, 3.2, 0, Math.PI * 2);
  ctx.arc(-10 * sx, by - 30 * sy + spoutLag * 2, 2.0, 0, Math.PI * 2);
  ctx.fill();

  ctx.restore();
}

