function drawMahoukarpWhaleShark(ctx, cx, cy, breath, angle, scale, time) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const sx = 1.0 + 0.05 * Math.cos(angle);
  const sy = 1.0 / Math.sqrt(sx);
  const by = Math.sin(angle) * 3.0;

  const tailLag = Math.sin(angle - 1.10);
  const finLag  = Math.sin(angle - 0.45);

  // Caudal Tail Fin
  ctx.save();
  ctx.translate(-36 * sx, by - 16 * sy + tailLag * 7.0);
  ctx.fillStyle = '#3D6CB3';
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(-18, -14);
  ctx.lineTo(-6, 2);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(-14, 12);
  ctx.lineTo(-4, -2);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  // Dorsal Fin
  ctx.fillStyle = '#3D6CB3';
  ctx.beginPath();
  ctx.moveTo(-12 * sx - 10, by - 22 * sy + 8 + finLag * 2);
  ctx.lineTo(-12 * sx + 4, by - 22 * sy + 8 + finLag * 2);
  ctx.lineTo(-12 * sx - 2, by - 22 * sy - 8 + finLag * 2);
  ctx.closePath();
  ctx.fill();

  // Body Gradient
  const bodyGrad = ctx.createLinearGradient(-40 * sx, by - 20 * sy, 40 * sx, by + 20 * sy);
  bodyGrad.addColorStop(0, '#3D6CB3');
  bodyGrad.addColorStop(0.5, '#68B8F6');
  bodyGrad.addColorStop(1, '#9BD0F5');
  ctx.fillStyle = bodyGrad;
  ctx.beginPath();
  ctx.ellipse(0, by, 44 * sx, 27 * sy, 0.1, 0, Math.PI * 2);
  ctx.fill();

  // Wide Pectoral Wings
  ctx.fillStyle = '#4B74B5';
  ctx.beginPath();
  ctx.ellipse(-18 * sx, by - 6 * sy + finLag * 3.5, 14, 7, -0.3, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#68B8F6';
  ctx.beginPath();
