function drawMahoukarpAbyssalAngler(ctx, cx, cy, breath, angle, scale, time) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const sy = 1.0 + 0.05 * Math.sin(angle);
  const sx = 1.0 / Math.sqrt(sy);
  const by = Math.sin(angle) * 3.0;

  const lanternLag = Math.sin(angle - 1.20);
  const lanternX = 32 * sx + lanternLag * 5.0;
  const lanternY = -24 * sy + lanternLag * 4.0;
  const tailLag = Math.sin(angle - 0.80);

  // Caudal Tail Fin
  ctx.save();
  ctx.translate(-32 * sx, by);
  ctx.fillStyle = '#2B3B6F';
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(-16, -12 + tailLag * 5.0);
  ctx.lineTo(-16, 12 + tailLag * 5.0);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#94E4FF';
  ctx.lineWidth = 1.2;
  ctx.stroke();
  ctx.restore();

  // Radiating Dorsal Spines
  for (let s = 0; s < 5; s++) {
    const spBaseX = (-14 + s * 7) * sx;
    const spBaseY = by - 18 * sy;
    const spTipX  = spBaseX - 3;
    const spTipY  = spBaseY - (8 + s * 2.2);
    ctx.strokeStyle = '#4D68B3';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(spBaseX, spBaseY);
    ctx.lineTo(spTipX, spTipY);
    ctx.stroke();
    // Glowing Tip
    ctx.fillStyle = '#54F0E8';
    ctx.beginPath();
    ctx.arc(spTipX, spTipY, 2.2, 0, Math.PI * 2);
    ctx.fill();
  }

  // Chubby Midnight Hull
  const bodyGrad = ctx.createRadialGradient(-4, by - 4, 4, 0, by, 26 * sx);
  bodyGrad.addColorStop(0, '#4D68B3');
  bodyGrad.addColorStop(0.6, '#2B3B6F');
  bodyGrad.addColorStop(1, '#182046');
  ctx.fillStyle = bodyGrad;
  ctx.beginPath();
  ctx.arc(0, by, 26 * sx, 0, Math.PI * 2);
  ctx.fill();

  // Pastel Cyan Jaw & Zigzag Teeth
  const jawY = by + 8 * sy;
  ctx.fillStyle = '#94E4FF';
  ctx.beginPath();
  ctx.ellipse(8 * sx, jawY, 18 * sx, 12 * sy, 0, 0, Math.PI);
  ctx.fill();
  // Teeth
  ctx.fillStyle = '#FFFFFF';
  for (let t = 0; t < 4; t++) {
    const tx = (-2 + t * 6) * sx;
    ctx.beginPath();
    ctx.moveTo(tx - 2.5, jawY);
    ctx.lineTo(tx, jawY - 4.5);
    ctx.lineTo(tx + 2.5, jawY);
    ctx.closePath();
    ctx.fill();
  }

  // Flexible Illucium Stalk
  ctx.strokeStyle = '#63D6F6';
  ctx.lineWidth = 2.2;
  ctx.beginPath();
  ctx.moveTo(4 * sx, by - 24 * sy);
  ctx.quadraticCurveTo(22 * sx, by - 40 * sy, lanternX, by + lanternY);
  ctx.stroke();

  // Glowing Esca Lantern Orb
  ctx.save();
  ctx.shadowColor = '#00F0FF';
  ctx.shadowBlur = 16;
  ctx.fillStyle = '#00F0FF';
  ctx.beginPath();
  ctx.arc(lanternX, by + lanternY, 7.5, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#FFFFFF';
  ctx.beginPath();
  ctx.arc(lanternX, by + lanternY, 3.2, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  // Lateral Bioluminescent Dots
  const dots = [[-14, -2], [-8, 4], [0, -6], [8, -2], [14, -8]];
  ctx.fillStyle = '#54F0E8';
  for (const d of dots) {
    ctx.beginPath();
    ctx.arc(d[0] * sx, by + d[1] * sy, 2.2, 0, Math.PI * 2);
    ctx.fill();
  }

