function drawMahoukarpStingray(ctx, cx, cy, breath, angle, scale, time) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const sx = 1.0 + 0.05 * Math.sin(angle);
  const sy = 1.0 / Math.sqrt(sx);
  const by = Math.sin(angle) * 3.5;

  const wingFlap = Math.sin(angle - 0.50);
  const wingTipY = wingFlap * 6.5;

  // Slender Kinematic Whip Tail
  const tailBaseX = 32 * sx, tailBaseY = by + 6 * sy;
  ctx.strokeStyle = '#77CBF7';
  ctx.lineWidth = 2.0;
  ctx.beginPath();
  ctx.moveTo(tailBaseX, tailBaseY);
  for (let seg = 1; seg <= 16; seg++) {
    const nextX = tailBaseX + seg * 3.2;
    const nextY = tailBaseY + Math.sin(angle - seg * 0.28) * 5.0;
    ctx.lineTo(nextX, nextY);
  }
  ctx.stroke();

  // Fairy Wings Kite Hull
  const wLX = -36 * sx, wLY = by - 12 * sy + wingTipY;
  const wRX = 34 * sx, wRY = by - 16 * sy - wingTipY;

  const wingGrad = ctx.createLinearGradient(-36 * sx, by, 34 * sx, by);
  wingGrad.addColorStop(0, '#F6A9CF');
  wingGrad.addColorStop(0.3, '#787BD6');
  wingGrad.addColorStop(0.7, '#77CBF7');
  wingGrad.addColorStop(1, '#F6A9CF');

  ctx.fillStyle = wingGrad;
  ctx.beginPath();
  ctx.moveTo(0, by - 18 * sy);
  ctx.lineTo(wLX, wLY);
  ctx.lineTo(0, by + 14 * sy);
  ctx.lineTo(wRX, wRY);
  ctx.closePath();
  ctx.fill();

  // Pearl White Underbelly
  ctx.fillStyle = '#FFFFFF';
  ctx.beginPath();
  ctx.ellipse(-4 * sx, by + 2 * sy, 26 * sx, 19 * sy, 0.05, 0, Math.PI * 2);
  ctx.fill();

  // Smiling Chibi Mouth
  const mX = -14 * sx, mY = by - 2 * sy;
  ctx.fillStyle = '#FF9CB8';
  ctx.beginPath();
  ctx.ellipse(mX, mY, 7 * sx, 5 * sy, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#E85D88';
  ctx.beginPath();
  ctx.arc(mX, mY + 1, 3.0, 0, Math.PI * 2);
  ctx.fill();

  // 3 Gill Slits
  ctx.strokeStyle = '#96D4F8';
  ctx.lineWidth = 1.5;
  for (let g = 0; g < 3; g++) {
    const gx = (-2 + g * 4.5) * sx;
    ctx.beginPath();
    ctx.moveTo(gx, by - 4 * sy);
    ctx.lineTo(gx, by + 2 * sy);
    ctx.stroke();
  }

  // Cephalic Flaps
  ctx.fillStyle = '#77CBF7';
  ctx.beginPath();
  ctx.arc(-26 * sx, by - 12 * sy, 4.0, 0, Math.PI * 2);
  ctx.fill();

  // Crystal Eye 3 Catchlights
  const eyeX = -4 * sx, eyeY = by - 8 * sy;
  const blink = (time % 3700 < 130);
  if (blink) {
    ctx.strokeStyle = '#101432';
    ctx.lineWidth = 1.8;
    ctx.beginPath();
    ctx.moveTo(eyeX - 3, eyeY);
    ctx.lineTo(eyeX + 3, eyeY);
    ctx.stroke();
  } else {
    ctx.fillStyle = '#101432';
    ctx.beginPath();
    ctx.arc(eyeX, eyeY, 3.8, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#FFFFFF';
    ctx.beginPath();
    ctx.arc(eyeX - 1.2, eyeY - 1.5, 1.6, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(eyeX + 1.2, eyeY + 1.0, 0.9, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#77CBF7';
    ctx.beginPath();
    ctx.arc(eyeX + 1.5, eyeY - 0.7, 0.6, 0, Math.PI * 2);
    ctx.fill();
  }

  // Cheek Blush
  ctx.fillStyle = '#FFAAC2';
  ctx.beginPath();
  ctx.ellipse(-18 * sx, by + 4 * sy, 4.5, 3.2, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.restore();
}

