  // Lower Base Shell
  ctx.fillStyle = '#617BC8';
  ctx.beginPath();
  ctx.ellipse(0, by + 18 * sy, 36 * sx, 16 * sy, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#7DB4F5';
  ctx.beginPath();
  ctx.ellipse(0, by + 17 * sy, 34 * sx, 14 * sy, 0, 0, Math.PI * 2);
  ctx.fill();

  // Velvet Nacre Cushion
  ctx.fillStyle = '#FFB8DA';
  ctx.beginPath();
  ctx.ellipse(0, by + 14 * sy, 28 * sx, 9 * sy, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#FFE6F4';
  ctx.beginPath();
  ctx.ellipse(0, by + 13 * sy, 24 * sx, 7 * sy, 0, 0, Math.PI * 2);
  ctx.fill();

  // Upper Fan Shell with 7 Fluted Ribs
  const upY = by - 10 * sy - shellLift;
  const ribAngles = [-30, -20, -10, 0, 10, 20, 30];
  const ribHeights = [20, 26, 30, 32, 30, 26, 20];
  for (let r = 0; r < 7; r++) {
    const rx = ribAngles[r] * 1.1 * sx;
    const ry = upY - ribHeights[r] * 0.4 * sy;
    ctx.fillStyle = (r % 2 === 0) ? '#ACC3EA' : '#7DB4F5';
    ctx.beginPath();
    ctx.ellipse(rx, ry, 8 * sx, 18 * sy, (ribAngles[r] * Math.PI) / 180, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.strokeStyle = '#FFFFFF';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.ellipse(0, upY - 8, 32 * sx, 16 * sy, 0, 0, Math.PI);
  ctx.stroke();

  // Living Pearl
  const pY = by + 8 * sy - Math.sin(angle - 0.60) * 2.0;
  const pRadius = 17 * sx;
  const pearlGrad = ctx.createRadialGradient(-3, pY - 3, 2, 0, pY, pRadius);
  pearlGrad.addColorStop(0, '#FFFFFF');
  pearlGrad.addColorStop(0.7, '#FFEBF6');
  pearlGrad.addColorStop(1, '#E2EFF9');

  ctx.fillStyle = pearlGrad;
  ctx.beginPath();
  ctx.arc(0, pY, pRadius, 0, Math.PI * 2);
  ctx.fill();

