  const sX = -6, sY = pY - 9;
  ctx.fillStyle = '#FFFFFF';
  ctx.beginPath();
  ctx.moveTo(sX, sY - 3.5);
  ctx.lineTo(sX + 2, sY);
  ctx.lineTo(sX, sY + 3.5);
  ctx.lineTo(sX - 2, sY);
  ctx.closePath();
  ctx.fill();

  // Pearl Kawaii Face (3 Catchlights)
  const eyeL = -6, eyeR = 6, eyeY = pY - 1;
  const blink = (time % 3400 < 130);
  function renderPearlEye(ex) {
    if (blink) {
      ctx.strokeStyle = '#151035';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(ex - 2.5, eyeY);
      ctx.lineTo(ex + 2.5, eyeY);
      ctx.stroke();
    } else {
      ctx.fillStyle = '#151035';
      ctx.beginPath();
      ctx.arc(ex, eyeY, 3.2, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#FFFFFF';
      ctx.beginPath();
      ctx.arc(ex - 1.0, eyeY - 1.2, 1.3, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.arc(ex + 1.0, eyeY + 0.8, 0.7, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#FFE6F4';
      ctx.beginPath();
      ctx.arc(ex + 1.2, eyeY - 0.6, 0.4, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  renderPearlEye(eyeL);
  renderPearlEye(eyeR);

  // Tiny Smile
  ctx.strokeStyle = '#151035';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.arc(0, eyeY + 2.5, 2.5, 0.1, Math.PI - 0.1);
  ctx.stroke();

  // Cheeks
  ctx.fillStyle = '#FF7AA2';
  ctx.beginPath();
  ctx.arc(-10, eyeY + 2, 3.2, 0, Math.PI * 2);
  ctx.arc(10, eyeY + 2, 3.2, 0, Math.PI * 2);
  ctx.fill();

  // Shimmering Pearl Bubbles
  const bubLag = Math.sin(angle - 1.40);
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.arc(-22 * sx, by - 20 * sy + bubLag * 4.0, 3.2, 0, Math.PI * 2);
  ctx.arc(24 * sx, by - 26 * sy - bubLag * 3.0, 2.4, 0, Math.PI * 2);
  ctx.stroke();

  ctx.restore();
}

